-- VITAWAW 1.16.1 info pages (owner: «اريدك ان تحدث هذه جميعها على المعلومات الجديده و الافكار الجديده و التصميم الجديد»).
-- Rewrites the text of the 8 help pages in the owner's DRAFT (who, about, howto, faq, method, privacy, disclaimer, suggest) for the
-- pharmacist-only site, the new tools and the new page design (## heading = card, - point, **bold**). Order, hidden flags and any other
-- page stay as they are; a page missing from the draft is added at the end. Visitors see it after the owner publishes. Safe to run twice.
insert into public.site_config (id, data, updated_at) select 'draft', data, now() from public.site_config where id = 'published'
  and not exists (select 1 from public.site_config where id = 'draft');
with np as (select value as p, value->>'id' as id from jsonb_array_elements($pg$[{"id": "who", "t": {"ar": "من نحن", "en": "About us"}, "b": {"ar": "VITAWAW مشروع أكاديمي في الصيدلة – جامعة الشرق الأوسط، بعنوان «حساب جرع الفيتامينات».\n\n## فريق العمل\n- الصيدلي **سيف الدين يحيى خليفة** (قائد الفريق)\n- عبد الرزاق عبد الجليل علي\n- راكان علي شهاب\n- بلال خلف\n\n## هدفنا\nتبسيط حساب جرعات الفيتامينات والمعادن للصيادلة، بالاعتماد على مصادر علمية رسمية يراجعها صيدلي قبل نشرها.\n\n## كيف نعمل\n- لكل رقم في الموقع مصدر رسمي يظهر رقمه بجانبه.\n- يضيف الصيادلة المدعوون المحتوى، ولا يظهر للزوار إلا بعد أن يعتمده الصيدلي المسؤول.\n- يُسجَّل كل تعديل في «سجل الإجراءات»: ماذا تغيّر، ومن غيّره، ومتى.", "en": "VITAWAW is an academic pharmacy project at Middle East University, titled «Vitamin dose calculation».\n\n## Team\n- Pharmacist **Saifaldeen Yahya Khalifa** (team leader)\n- Abdulrazzaq Abduljaleel Ali\n- Rakan Ali Shehab\n- Bilal Khalaf\n\n## Our aim\nTo make vitamin and mineral dosing simpler for pharmacists, based on official scientific sources that a pharmacist reviews before they are published.\n\n## How we work\n- Every number on the site has an official source whose number appears next to it.\n- Invited pharmacists add content; visitors see it only after the responsible pharmacist approves it.\n- Every change is recorded in the «Activity log»: what changed, who changed it and when."}}, {"id": "about", "t": {"ar": "حول التطبيق", "en": "About the app"}, "b": {"ar": "VITAWAW حاسبة لجرعات الفيتامينات والمعادن **للصيادلة**، مبنية على مصادر طبية رسمية.\n\n## ماذا يقدّم\n- **الحاسبة:** الفيتامينات والمعادن الأساسية، وحاسبات خاصة: الحمل والرضاعة، الرضيع، فيتامين A للأطفال، بعد عمليات السمنة، نقص فيتامين B1، والزنك لإسهال الأطفال.\n- **التداخلات:** تداخلات المكملات مع الأدوية وفواصل الأخذ، من نشرات الأدوية والمراجع الرسمية، مرتبة حسب الخطورة.\n- **أدوية المريض:** أضف أدوية المريض من قائمة أبجدية فتظهر تداخلاتها فقط.\n- **الأدوات:** عدد الحبات، محوّل فيتامين D، الكالسيوم المصحح، عجز الحديد (Ganzoni)، الشراب والقطرات، محوّل الوحدات.\n- **أدوات المتابعة:** جدول المكملات اليومي، الحد الأعلى الآمن، سجل التحاليل.\n- **المصادر:** قائمة كاملة بنوع كل مصدر وأين يُستخدم.\n\n## لماذا تثق بالنتيجة\n- بجانب كل رقم رقم مصدره، اضغطه لفتح المصدر.\n- يراجع صيدلي كل إضافة قبل أن تظهر للزوار.\n\n## على الهاتف\nمن القائمة ← الإعدادات ← «تثبيت على الهاتف» يفتح VITAWAW كتطبيق من الشاشة الرئيسية.", "en": "VITAWAW is a vitamin and mineral dose calculator **for pharmacists**, built on official medical sources.\n\n## What it offers\n- **Calculator:** the main vitamins and minerals, and special calculators: pregnancy and breastfeeding, infants, vitamin A for children, after weight-loss surgery, vitamin B1 deficiency, and zinc for childhood diarrhoea.\n- **Interactions:** supplement–medicine interactions and timing gaps, from drug labels and official references, sorted by severity.\n- **Patient medicines:** add the patient's medicines from an A–Z list to see only their interactions.\n- **Tools:** tablet counter, vitamin D converter, corrected calcium, iron deficit (Ganzoni), syrups and drops, unit converter.\n- **Follow-up tools:** daily supplement schedule, safe upper limit, lab results log.\n- **Sources:** the full list, with the type of each source and where it is used.\n\n## Why you can trust the result\n- Every number shows the number of its source; tap it to open the source.\n- A pharmacist reviews every addition before visitors can see it.\n\n## On your phone\nMenu → Settings → «Install on phone» opens VITAWAW as an app from the home screen."}}, {"id": "howto", "t": {"ar": "طريقة الاستخدام", "en": "How to use"}, "b": {"ar": "## ١. احسب الجرعة\n- اختر الفيتامين أو المعدن من المربعات، أو إحدى الحاسبات الخاصة.\n- أدخل العمر والجنس ونتيجة التحليل إن وُجدت.\n- تظهر النتيجة فوراً: الجرعة والخطة والتحذيرات، وبجانب كل رقم رقم مصدره.\n\n## ٢. من النتيجة إلى التطبيق\n- أزرار تحت النتيجة تفتح الأداة معبّأة: عدد الحبات أو القطرات أو المل، جدول المكملات، التقويم.\n- **بطاقة المريض** تسلّمها للمريض، و**تقرير للطبيب** للطباعة أو PDF، و**شارك برابط** ليفتح غيرك النتيجة نفسها.\n\n## ٣. التداخلات وأدوية المريض\n- في «التداخلات» اختر المكمّل من الأزرار أو ابحث باسم الدواء.\n- في «أدوية المريض» أضف أدويته من القائمة الأبجدية (أ – ي أو A – Z) لترى تداخلاتها فقط.\n\n## ٤. جدول المكملات\n- اختر المكملات والأدوية، أو اضغط «أضف أدوية المريض».\n- تُرتَّب الأوقات تلقائياً حسب الفواصل من النشرات، ثم «أضف إلى التقويم».\n\n## ٥. المتابعة\n- «الحد الأعلى» يجمع ما في كل المكملات وينبّه إذا تجاوز الحد الآمن.\n- «سجل التحاليل» يحفظ النتائج على هذا الجهاز ويرسم التحسن بين تحليل وآخر.", "en": "## 1. Work out the dose\n- Choose the vitamin or mineral from the tiles, or one of the special calculators.\n- Enter age, sex and the lab result if there is one.\n- The result appears at once: dose, plan and warnings, with the source number next to every number.\n\n## 2. From the result to practice\n- Buttons under the result open the tool already filled in: tablets, drops or mL, the supplement schedule, the calendar.\n- **Patient card** to hand to the patient, **Report for the doctor** to print or save as PDF, and **Share by link** so someone else opens the same result.\n\n## 3. Interactions and patient medicines\n- In «Interactions» pick the supplement from the buttons or search by medicine name.\n- In «Patient medicines» add the patient's medicines from the A–Z list to see only their interactions.\n\n## 4. Supplement schedule\n- Choose the supplements and medicines, or tap «Add the patient medicines».\n- The times are arranged automatically by the gaps from the labels; then «Add to calendar».\n\n## 5. Follow-up\n- «Upper limit» adds up every supplement and warns if the total passes the safe limit.\n- «Lab results log» keeps results on this device and charts the change from one test to the next."}}, {"id": "faq", "t": {"ar": "الأسئلة الشائعة", "en": "Frequently asked questions"}, "b": {"ar": "## لمن التطبيق؟\nللصيادلة. تظهر النتيجة كاملة مع رقم مصدر كل جرعة والبدائل والتحذيرات، ومنها «بطاقة المريض» و«تقرير للطبيب» لتسليمهما للمريض أو الطبيب.\n\n## من أين تأتي الأرقام؟\nمن إرشادات سريرية ومراجع رسمية ونشرات الأدوية. اضغط رقم المصدر بجانب أي رقم لفتحه، وكل المصادر في صفحة «المصادر».\n\n## هل تُحفظ بيانات المريض؟\nلا. ما تدخله يبقى على جهازك. «سجل التحاليل» و«أدوية المريض» و«جدول المكملات» تُحفظ على هذا الجهاز فقط، وتحذفها من القائمة ← «امسح بياناتي من هذا الجهاز».\n\n## كيف أحوّل الجرعة إلى حبات أو قطرات أو مل؟\nتحت النتيجة أزرار تفتح الأداة المناسبة معبّأة: كم حبة، كم قطرة، كم مل من الشراب.\n\n## كيف أرتّب المكملات مع أدوية المريض؟\nافتح «جدول المكملات» واضغط «أضف أدوية المريض»، فتُرتَّب الأوقات تلقائياً بحيث تُحترم الفواصل، ثم «أضف إلى التقويم».\n\n## كيف أعرض النتيجة على الطبيب؟\n«تقرير للطبيب» ثم «اطبع أو احفظ PDF»، أو «شارك برابط» ليفتح الطبيب الحاسبة بالقيم نفسها.\n\n## هل يغني عن الطبيب؟\nلا. التطبيق يساعد الصيدلي والطبيب ولا يحل محلهما، خاصة في الحمل والأطفال ومرضى الكلى.", "en": "## Who is the app for?\nPharmacists. The result shows everything, with the source number of each dose, alternatives and warnings, plus a «Patient card» and a «Report for the doctor» to hand to the patient or the doctor.\n\n## Where do the numbers come from?\nFrom clinical guidelines, official references and drug labels. Tap the source number next to any number to open it; every source is on the «Sources» page.\n\n## Is the patient's data saved?\nNo. What you enter stays on your device. «Lab results log», «Patient medicines» and «Supplement schedule» are kept on this device only; delete them from Menu → «Clear my data from this device».\n\n## How do I turn a dose into tablets, drops or mL?\nUnder the result, buttons open the right tool already filled in: tablets, drops, mL of syrup.\n\n## How do I arrange supplements with the patient's medicines?\nOpen «Supplement schedule» and tap «Add the patient medicines»; the times are arranged so every gap is respected, then «Add to calendar».\n\n## How do I show the result to a doctor?\n«Report for the doctor» then «Print or save as PDF», or «Share by link» so the doctor opens the calculator with the same values.\n\n## Does it replace a doctor?\nNo. The app supports pharmacists and doctors and does not replace them, especially in pregnancy, children and kidney disease."}}, {"id": "method", "t": {"ar": "المنهجية العلمية", "en": "Scientific method"}, "b": {"ar": "## اختيار المصادر\nكل جرعة وكل حد مأخوذ من مصدر موثوق يظهر رقمه بجانبه. ترتيب الأولوية:\n- **الإرشادات السريرية:** Endocrine Society وNICE وWHO وAAP وBSG وKDIGO وASMBS.\n- **المراجع الرسمية:** NIH Office of Dietary Supplements للاحتياج والحد الأعلى، وNHS وBNF.\n- **نشرات الأدوية الرسمية:** FDA وSmPC وMedsafe للتداخلات والفواصل.\n- **المراجعات المنهجية:** Cochrane.\nلا تُستخدم مواقع ثانوية عندما يوجد مصدر أصلي.\n\n## عند اختلاف الإرشادات\nتذكر النتيجة الخلاف بوضوح، مثل الفرق بين إرشاد فيتامين D لعام 2011 ولعام 2024، ولا يُخفى أي رأي.\n\n## المراجعة والاعتماد\n- كل إضافة أو تعديل يكتبه صيدلي من الفريق يبقى غير ظاهر للزوار حتى يراجعه الصيدلي المسؤول ويعتمده وينشره.\n- قاعدة البيانات نفسها تفرض ذلك، وتحفظ كل نسخة منشورة.\n- «سجل الإجراءات» يسجّل كل تعديل ومن قام به ومتى.\n\n## التحقق\n- تُختبر الحاسبات آلياً على **66 حالة طبية** ثابتة تقارن النتيجة بما يقوله المصدر.\n- تُختبر الأدوات ومعادلاتها وفواصل جدول المكملات في **100 فحص**.\n- تُفحص روابط المصادر بانتظام، وتُشغَّل الاختبارات تلقائياً مع كل تحديث.\n\n## الحدود\nالتطبيق أداة مساعدة تعليمية ولا يغني عن التقييم السريري. الحالات الخاصة (الحمل عالي الخطورة، القصور الكلوي، الأطفال) تُحال إلى الطبيب المختص.", "en": "## Choosing sources\nEvery dose and limit comes from a trusted source whose number appears next to it. Order of priority:\n- **Clinical guidelines:** Endocrine Society, NICE, WHO, AAP, BSG, KDIGO, ASMBS.\n- **Official references:** NIH Office of Dietary Supplements for needs and upper limits, NHS and BNF.\n- **Official drug labels:** FDA, SmPC and Medsafe for interactions and timing.\n- **Systematic reviews:** Cochrane.\nSecondary websites are not used where a primary source exists.\n\n## When guidelines differ\nThe result states the difference clearly, for example between the 2011 and 2024 vitamin D guidelines, and no view is hidden.\n\n## Review and approval\n- Every addition or edit by a team pharmacist stays hidden from visitors until the responsible pharmacist reviews, approves and publishes it.\n- The database itself enforces this and keeps every published version.\n- The «Activity log» records every change, who made it and when.\n\n## Validation\n- The calculators are tested automatically on **66 fixed medical cases** that compare the result with the source.\n- The tools, their formulas and the schedule gaps are tested in **100 checks**.\n- Source links are checked regularly, and the tests run automatically with every update.\n\n## Limits\nThe app is an educational support tool and does not replace clinical assessment. Special situations (high-risk pregnancy, kidney disease, children) are referred to the specialist."}}, {"id": "privacy", "t": {"ar": "سياسة الخصوصية", "en": "Privacy policy"}, "b": {"ar": "## لا نجمع بياناتك\nالعمر والوزن ونتائج التحاليل التي تدخلها تبقى على جهازك فقط ولا تُرسل لأي جهة. لا يحتاج الزائر حساباً.\n\n## بلا تتبّع\nلا أدوات تتبّع ولا إعلانات، والخطوط محمّلة من موقعنا نفسه.\n\n## ما يُحفظ على جهازك\n- إعداداتك: اللغة والمظهر وآخر قسم فتحته.\n- ما تختار حفظه بنفسك: «سجل التحاليل» و«أدوية المريض» و«جدول المكملات».\n- تحذفها كلها في أي وقت من القائمة ← «امسح بياناتي من هذا الجهاز».\n\n## الروابط المشتركة\nرابط «شارك برابط» يحمل القيم التي أدخلتها فقط، ولا تُحفظ في أي مكان.\n\n## حسابات الفريق\nالحسابات للمالك والصيادلة المدعوين فقط، وتُحفظ في قاعدة بيانات محمية، ويُسجَّل ما يغيّرونه في المحتوى.", "en": "## We do not collect your data\nThe age, weight and lab results you enter stay on your device and are never sent anywhere. Visitors need no account.\n\n## No tracking\nNo trackers and no ads; fonts are served from our own site.\n\n## What is kept on your device\n- Your settings: language, appearance and the last section you opened.\n- What you choose to save: «Lab results log», «Patient medicines» and «Supplement schedule».\n- Delete all of it at any time from Menu → «Clear my data from this device».\n\n## Shared links\nA «Share by link» link carries only the values you entered; they are not stored anywhere.\n\n## Team accounts\nAccounts are for the owner and invited pharmacists only, kept in a protected database, and their changes to the content are recorded."}}, {"id": "disclaimer", "t": {"ar": "إخلاء المسؤولية", "en": "Disclaimer"}, "b": {"ar": "## للتثقيف ومساعدة الصيدلي\nالمعلومات في التطبيق للتثقيف ولمساعدة الصيدلي والطبيب، ولا تغني عن الاستشارة الطبية.\n\n## قبل أي جرعة علاجية\n- لا تبدأ جرعة علاجية ولا توقفها دون مراجعة الطبيب أو الصيدلي.\n- احرص أكثر في الحمل والأطفال ومرضى الكلى.\n- اتبع وصفة الطبيب إذا اختلفت عن النتيجة.", "en": "## For education and to support pharmacists\nThe information in this app is for education and to support pharmacists and doctors; it does not replace medical advice.\n\n## Before any treatment dose\n- Do not start or stop a treatment dose without a doctor or pharmacist.\n- Take extra care in pregnancy, children and kidney disease.\n- Follow the doctor's prescription if it differs from the result."}}, {"id": "suggest", "t": {"ar": "اقترح ميزة أو أبلغ عن خطأ", "en": "Suggest a feature or report an error"}, "b": {"ar": "نقرأ كل رسالة ونرد عليها.\n\n## ماذا تكتب لنا\n- **ميزة تحتاجها:** حاسبة أو أداة أو تداخل غير موجود.\n- **رقم يحتاج مراجعة:** اذكر الحاسبة والقيم التي أدخلتها ورقم المصدر.\n- **خطأ في الشكل:** اذكر الجهاز (هاتف أو آيباد أو كمبيوتر) والصفحة.", "en": "We read and answer every message.\n\n## What to tell us\n- **A feature you need:** a calculator, tool or interaction that is missing.\n- **A number that needs checking:** name the calculator, the values you entered and the source number.\n- **A layout problem:** name the device (phone, iPad or computer) and the page."}}]$pg$::jsonb))
update public.site_config c set updated_at = now(), data = jsonb_set(c.data, '{pages}',
  coalesce((select jsonb_agg(case when np.p is null then o.p else o.p || jsonb_build_object('t', np.p->'t', 'b', np.p->'b') end order by o.n)
     from jsonb_array_elements(coalesce(c.data->'pages', '[]'::jsonb)) with ordinality as o(p, n) left join np on np.id = o.p->>'id'), '[]'::jsonb)
  || coalesce((select jsonb_agg(np.p) from np where not exists (select 1 from jsonb_array_elements(coalesce(c.data->'pages', '[]'::jsonb)) x where x->>'id' = np.id)), '[]'::jsonb))
 where c.id = 'draft';
